package vn.rtr.aeris.mission;
import android.content.*;import android.os.*;import android.system.*;import android.util.Log;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Read-only product observation. It cannot select a mission or grant control. */
public final class ProductStatusReceiver extends BroadcastReceiver {
 private static final ThreadPoolExecutor IO=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<Runnable>(1));
 private static final AtomicInteger REQUESTS=new AtomicInteger();
 @Override public void onReceive(Context context,Intent intent){String nonce=intent.getStringExtra("requestNonce");if(!"vn.rtr.aeris.mission.PRODUCT_STATUS".equals(intent.getAction())||nonce==null||!nonce.matches("[a-f0-9]{32}")||REQUESTS.incrementAndGet()>900)return;final PendingResult result=goAsync();try{IO.execute(()->{try{publish(context,nonce);}catch(Exception e){Log.e("AERIS_PRODUCT_STATUS_FAILURE",String.valueOf(e.getMessage()));}finally{result.finish();}});}catch(RejectedExecutionException e){result.finish();Log.e("AERIS_PRODUCT_STATUS_FAILURE","STATUS_BUSY_NO_QUEUE");}}
 private static long[] counts(File root)throws Exception{ArrayDeque<File> todo=new ArrayDeque<>();todo.add(root.getCanonicalFile());long logical=0,allocated=0,entries=0;while(!todo.isEmpty()){File f=todo.removeFirst();if(++entries>8192||!f.getCanonicalFile().equals(f.getAbsoluteFile()))throw new IOException("STATUS_PRIVATE_FILES_SHAPE");StructStat s=Os.lstat(f.getPath());allocated+=s.st_blocks*512;if(f.isDirectory()){File[] xs=f.listFiles();if(xs==null)throw new IOException("STATUS_PRIVATE_FILES_LIST");Collections.addAll(todo,xs);}else if(f.isFile())logical+=s.st_size;else throw new IOException("STATUS_PRIVATE_FILES_TYPE");}return new long[]{logical,allocated,entries};}
 private static void publish(Context context,String nonce)throws Exception{
  byte[] identity;try(InputStream in=context.getAssets().open("source-identity.json")){identity=WorkspaceStore.read(in,16384);}JSONObject source=new JSONObject(new String(identity,StandardCharsets.UTF_8));
  File dir=new File(context.getFilesDir().getCanonicalFile(),"product-observations01");if(!dir.isDirectory()&&!dir.mkdir())throw new IOException("STATUS_DIRECTORY");if(!dir.getCanonicalFile().equals(dir.getAbsoluteFile()))throw new IOException("STATUS_DIRECTORY_SYMLINK");File[] existing=dir.listFiles();if(existing==null||existing.length>=900)throw new IOException("STATUS_DOCUMENT_COUNT");long[] before=counts(context.getFilesDir());if(before[0]+16384>512L*1024*1024||before[1]+32768>160L*1024*1024)throw new IOException("STATUS_PRIVATE_FILES_QUOTA");
  File checkpoint=new File(context.getFilesDir().getCanonicalFile(),"checkpoint14");long checkpointBytes=0,checkpointCount=0;if(checkpoint.exists()){File[] archives=checkpoint.listFiles();if(archives==null)throw new IOException("CHECKPOINT_READ_ONLY_LIST");for(File f:archives)if(f.getName().matches("terminal-[a-f0-9]{64}\\.json")){if(!f.isFile()||!f.getCanonicalFile().equals(f.getAbsoluteFile()))throw new IOException("CHECKPOINT_REGULAR_FILE");checkpointBytes+=f.length();checkpointCount++;}if(checkpointBytes>512*1024||checkpointCount>8)throw new IOException("CHECKPOINT_ORIGINAL_QUOTA");}
  JSONObject snapshot=new JSONObject().put("format","aeris-betasim-native-status").put("version",1).put("requestNonce",nonce).put("observedElapsedNs",SystemClock.elapsedRealtimeNanos()).put("processEpoch",NativeInputBridge.PROCESS_EPOCH).put("pid",android.os.Process.myPid()).put("package","vn.rtr.aeris.mission").put("sourceSHA256",source.getString("sourceSHA256")).put("sourceIdentity",source).put("input",new JSONObject(ProductActivity.inputSnapshot())).put("webGeometry",new JSONObject(ProductActivity.webGeometrySnapshot())).put("authorityRestorable",false).put("actualImages",0).put("inventory",new JSONObject().put("scope","PRIVATE_FILES_ONLY_NOT_WHOLE_APP_DATA_DIR").put("logicalBytes",before[0]).put("allocatedBytes",before[1]).put("entries",before[2]).put("checkpointArchiveBytes",checkpointBytes).put("checkpointArchiveCount",checkpointCount).put("measuredBeforeOwnSnapshotWrite",true)).put("workspaceNamespace","betasim-workspace01").put("exportBudget",new JSONObject(ProductActivity.exportSnapshot()));
  byte[] bytes=snapshot.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>16384)throw new IOException("STATUS_16KIB");File output=new File(dir,"status-"+nonce+".json");if(!output.createNewFile())throw new IOException("STATUS_NONCE_REPLAY");try(FileOutputStream stream=new FileOutputStream(output)){stream.write(bytes);stream.getFD().sync();}FileDescriptor fd=Os.open(dir.getPath(),OsConstants.O_RDONLY,0);try{Os.fsync(fd);}finally{Os.close(fd);}
  Log.i("AERIS_PRODUCT_STATUS",new JSONObject().put("version",1).put("requestNonce",nonce).put("path","files/product-observations01/"+output.getName()).put("sha256",WorkspaceStore.sha(bytes)).put("bytes",bytes.length).put("processEpoch",NativeInputBridge.PROCESS_EPOCH).put("pid",android.os.Process.myPid()).toString());
 }
}
